INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'agony', 'n.', '/ˈæɡəni/', '痛苦;极大的痛苦', 'She was in agony after her best friend let her down.', '好友辜负了她之后,她痛苦极了。', 'Knowing Me Knowing You', 1, 0, 'senior', 'wordlist', 'required3', 'U1', 'in agony', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'agony aunt', 'n.', '/ˈæɡəni ɑːnt/', '(报刊的)知心姐姐,情感专栏作者', 'Ben wrote to an agony aunt for advice about his friendship problem.', '本写信向知心姐姐请教他的友谊问题。', 'Knowing Me Knowing You', 2, 0, 'senior', 'wordlist', 'required3', 'U1', 'write to an agony aunt', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'help out', 'v.', '/help aʊt/', '帮一把,帮忙', 'When a friend is in trouble, we should be ready to help out.', '朋友有难时,我们应随时准备帮一把。', 'Knowing Me Knowing You', 3, 0, 'senior', 'wordlist', 'required3', 'U1', 'help a friend out', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'let down', 'v.', '/let daʊn/', '使失望;辜负', 'He felt the team had been let down by one careless player.', '他觉得整个球队被一名粗心的队员辜负了。', 'Knowing Me Knowing You', 4, 0, 'senior', 'wordlist', 'required3', 'U1', 'let the team down', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'steam', 'n.', '/stiːm/', '蒸汽;水汽', 'When we hold in anger, the pressure builds up like steam.', '当我们压住怒火,压力会像蒸汽一样积聚。', 'Knowing Me Knowing You', 5, 0, 'senior', 'wordlist', 'required3', 'U1', 'build up like steam', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'let off steam', 'v.', '/let ɒf stiːm/', '发泄怒火,宣泄情绪', 'I was only letting off steam when I complained about my teammate.', '我抱怨队友只是在发泄情绪。', 'Knowing Me Knowing You', 6, 0, 'senior', 'wordlist', 'required3', 'U1', 'let off steam', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'loose', 'adj.', '/luːs/', '松的;不加约束的;随意的', 'A loose word said in anger can hurt a friendship badly.', '气头上随口说的一句话会严重伤害友谊。', 'Knowing Me Knowing You', 7, 0, 'senior', 'wordlist', 'required3', 'U1', 'loose words', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'lip', 'n.', '/lɪp/', '嘴唇', 'There is an old saying that loose lips can sink a friendship.', '有句老话说,口无遮拦会毁掉一段友谊。', 'Knowing Me Knowing You', 8, 0, 'senior', 'wordlist', 'required3', 'U1', 'loose lips', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'sink', 'v.', '/sɪŋk/', '(使)下沉;(使)沉没', 'Careless words can sink a friendship just as they sink a ship.', '不慎的言语会像弄沉船只一样毁掉友谊。', 'Knowing Me Knowing You', 9, 0, 'senior', 'wordlist', 'required3', 'U1', 'sink a ship', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'loose lips sink ships', 'phr.', '/luːs lɪps sɪŋk ʃɪps/', '祸从口出', 'Remember that loose lips sink ships, so be careful what you share.', '记住祸从口出,所以分享时要小心。', 'Knowing Me Knowing You', 10, 0, 'senior', 'wordlist', 'required3', 'U1', 'loose lips sink ships', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'fault', 'n.', '/fɔːlt/', '过错;责任', 'Instead of blaming others, he admitted that it was his own fault.', '他没有责怪别人,而是承认那是自己的过错。', 'Knowing Me Knowing You', 11, 0, 'senior', 'wordlist', 'required3', 'U1', 'one''s own fault', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'resolve', 'v.', '/rɪˈzɒlv/', '解决(问题、困难)', 'Honest communication is the best way to resolve a conflict with a friend.', '坦诚沟通是解决与朋友冲突的最好办法。', 'Knowing Me Knowing You', 12, 0, 'senior', 'wordlist', 'required3', 'U1', 'resolve a conflict', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'strategy', 'n.', '/ˈstrætədʒi/', '策略;计谋;行动计划', 'Her strategy for keeping friends is to listen before she speaks.', '她维系朋友的策略是先倾听再开口。', 'Knowing Me Knowing You', 13, 0, 'senior', 'wordlist', 'required3', 'U1', 'a clear strategy', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'signal', 'n.', '/ˈsɪɡnəl/', '信号;暗示', 'Saying nothing can sometimes send the wrong signal to your friends.', '有时什么都不说反而会给朋友错误的信号。', 'Knowing Me Knowing You', 14, 0, 'senior', 'wordlist', 'required3', 'U1', 'the wrong signal', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'breath', 'n.', '/breθ/', '呼吸;一口气', 'Take a deep breath and calm down before you say something you regret.', '在说出会后悔的话之前,先深吸一口气冷静下来。', 'Knowing Me Knowing You', 15, 0, 'senior', 'wordlist', 'required3', 'U1', 'a deep breath', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'take a breath', 'v.', '/teɪk ə breθ/', '吸一口气', 'Take a breath, calm down, and remember to think first and speak later.', '吸一口气,冷静下来,记住先思考后开口。', 'Knowing Me Knowing You', 16, 0, 'senior', 'wordlist', 'required3', 'U1', 'take a breath', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'pull one''s weight', 'v.', '/pʊl wʌnz weɪt/', '做好分内事,尽责', 'If a teammate is not pulling their weight, raise it with the coach politely.', '如果有队友没尽到本分,礼貌地跟教练提出来。', 'Knowing Me Knowing You', 17, 0, 'senior', 'wordlist', 'required3', 'U1', 'pull one''s weight', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'concern', 'n.', '/kənˈsɜːn/', '担心,忧虑;关心', 'She raised her concern about the problem in a polite and professional way.', '她以礼貌而得体的方式提出了对这个问题的担忧。', 'Knowing Me Knowing You', 18, 0, 'senior', 'wordlist', 'required3', 'U1', 'raise a concern', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'annoyed', 'adj.', '/əˈnɔɪd/', '恼怒的,烦恼的', 'I felt annoyed when my friend repeated my words to everyone.', '朋友把我的话转告给所有人时,我感到很恼火。', 'Knowing Me Knowing You', 19, 0, 'senior', 'wordlist', 'required3', 'U1', 'feel annoyed', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'adjust', 'v.', '/əˈdʒʌst/', '适应;调整', 'It took him a while to adjust to his new classmates after moving.', '搬来之后,他过了一阵子才适应新同学。', 'Knowing Me Knowing You', 20, 0, 'senior', 'wordlist', 'required3', 'U1', 'adjust to', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'duty', 'n.', '/ˈdjuːti/', '职责;义务;责任', 'As a good friend, it is your duty to be honest and kind.', '作为好朋友,诚实善良是你的责任。', 'Knowing Me Knowing You', 21, 0, 'senior', 'wordlist', 'required3', 'U1', 'do one''s duty', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'accident', 'n.', '/ˈæksɪdənt/', '意外事件;偶然', 'Hurting his feelings was an accident, so I apologised at once.', '伤了他的感情是个意外,所以我立刻道歉了。', 'Knowing Me Knowing You', 22, 0, 'senior', 'wordlist', 'required3', 'U1', 'by accident', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'by accident', 'adv.', '/baɪ ˈæksɪdənt/', '偶然,意外地', 'She let out his secret by accident and felt terribly sorry.', '她无意中说漏了他的秘密,感到非常抱歉。', 'Knowing Me Knowing You', 23, 0, 'senior', 'wordlist', 'required3', 'U1', 'by accident', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'core', 'adj.', '/kɔː/', '核心的;最重要的', 'Trust is the core value of any close friendship.', '信任是任何亲密友谊的核心价值。', 'Knowing Me Knowing You', 24, 0, 'senior', 'wordlist', 'required3', 'U1', 'a core value', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'ensure', 'v.', '/ɪnˈʃʊə/', '确保,保证', 'Clear communication helps to ensure that small problems do not grow.', '清晰的沟通有助于确保小问题不会扩大。', 'Knowing Me Knowing You', 25, 0, 'senior', 'wordlist', 'required3', 'U1', 'ensure that', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'complexity', 'n.', '/kəmˈpleksɪti/', '复杂性,错综复杂', 'Growing up means learning to deal with the complexity of human emotions.', '成长意味着学会应对人类情感的复杂性。', 'Knowing Me Knowing You', 26, 0, 'senior', 'wordlist', 'required3', 'U1', 'the complexity of', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'forgive', 'v.', '/fəˈɡɪv/', '原谅,宽恕', 'It is not easy to forgive a friend who has let you down.', '原谅一个让你失望的朋友并不容易。', 'Knowing Me Knowing You', 27, 0, 'senior', 'wordlist', 'required3', 'U1', 'forgive a friend', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'criticise', 'v.', '/ˈkrɪtɪsaɪz/', '批评,指责', 'Try not to criticise someone in front of others, as it causes embarrassment.', '尽量不要当众批评别人,因为那会造成尴尬。', 'Knowing Me Knowing You', 28, 0, 'senior', 'wordlist', 'required3', 'U1', 'criticise someone', '美式拼 criticize;美音 /ˈkrɪtɪsaɪz/', 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'embarrassment', 'n.', '/ɪmˈbærəsmənt/', '尴尬,难为情', 'Telling a small lie to avoid embarrassment can still hurt trust.', '为避免尴尬而撒个小谎仍会损害信任。', 'Knowing Me Knowing You', 29, 0, 'senior', 'wordlist', 'required3', 'U1', 'cause embarrassment', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'boxing', 'n.', '/ˈbɒksɪŋ/', '拳击(运动)', 'He invited me to watch a boxing match, but I politely said no.', '他邀我看拳击比赛,但我礼貌地拒绝了。', 'Knowing Me Knowing You', 30, 0, 'senior', 'wordlist', 'required3', 'U1', 'a boxing match', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'tangled', 'adj.', '/ˈtæŋɡld/', '纠结的;错综复杂的', 'Lies often leave us in a tangled web that is hard to escape.', '谎言常让我们陷入难以脱身的纠结之网。', 'Knowing Me Knowing You', 31, 0, 'senior', 'wordlist', 'required3', 'U1', 'a tangled web', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'web', 'n.', '/web/', '网;错综复杂的事物', 'One small lie can grow into a tangled web of bigger ones.', '一个小谎言会发展成更大谎言交织的复杂网络。', 'Knowing Me Knowing You', 32, 0, 'senior', 'wordlist', 'required3', 'U1', 'a web of lies', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'weave', 'v.', '/wiːv/', '编,织', 'When we begin to deceive, we weave a web of lies around ourselves.', '当我们开始欺骗,就在自己周围织起了一张谎言之网。', 'Knowing Me Knowing You', 33, 0, 'senior', 'wordlist', 'required3', 'U1', 'weave a web', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'deceive', 'v.', '/dɪˈsiːv/', '欺骗', 'A white lie is still an attempt to deceive someone we care about.', '善意的谎言仍是试图欺骗我们在乎的人。', 'Knowing Me Knowing You', 34, 0, 'senior', 'wordlist', 'required3', 'U1', 'deceive someone', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'justify', 'v.', '/ˈdʒʌstɪfaɪ/', '证明……有道理;为……辩护', 'Many people try to justify telling white lies to protect others.', '许多人试图为说善意谎言辩护,说是为了保护别人。', 'Knowing Me Knowing You', 35, 0, 'senior', 'wordlist', 'required3', 'U1', 'justify a lie', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'frank', 'adj.', '/fræŋk/', '坦率的,直言不讳的', 'A true friend gives you frank comments so that you can improve.', '真正的朋友会给你坦率的意见,好让你进步。', 'Knowing Me Knowing You', 36, 0, 'senior', 'wordlist', 'required3', 'U1', 'frank comments', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'tear', 'n.', '/tɪə/', '眼泪,泪水', 'She hid her tears and lied that her day had been fine.', '她藏起眼泪,谎称这一天过得很好。', 'Knowing Me Knowing You', 37, 0, 'senior', 'wordlist', 'required3', 'U1', 'hide one''s tears', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'latter', 'n.', '/ˈlætə/', '后者', 'If you must choose between truth and a lie, never pick the latter.', '如果必须在真话和谎言间选择,绝不要选后者。', 'Knowing Me Knowing You', 38, 0, 'senior', 'wordlist', 'required3', 'U1', 'the latter', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'moreover', 'adv.', '/mɔːrˈəʊvə/', '此外,而且', 'He repeated my words; moreover, he made the whole situation worse.', '他转述了我的话;而且,他还把整件事弄得更糟。', 'Knowing Me Knowing You', 39, 0, 'senior', 'wordlist', 'required3', 'U1', 'moreover', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'independent', 'adj.', '/ˌɪndɪˈpendənt/', '独立的', 'Being independent does not mean you never need your friends'' help.', '独立并不意味着你永远不需要朋友的帮助。', 'Knowing Me Knowing You', 40, 0, 'senior', 'wordlist', 'required3', 'U1', 'be independent', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'apart', 'adv.', '/əˈpɑːt/', '分离,分开;相隔', 'A small misunderstanding can slowly push two close friends apart.', '一个小误会会慢慢把两个亲密的朋友推远。', 'Knowing Me Knowing You', 41, 0, 'senior', 'wordlist', 'required3', 'U1', 'drift apart', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'fence', 'n.', '/fens/', '栅栏,围栏,篱笆', 'As the proverb says, a good fence between neighbours keeps a friendly distance.', '正如谚语所说,邻里之间一道好篱笆能保持友好的距离。', 'Knowing Me Knowing You', 42, 0, 'senior', 'wordlist', 'required3', 'U1', 'a good fence', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'conflict', 'n.', '/ˈkɒnflɪkt/', '冲突,矛盾', 'Clear communication is the best way to deal with a conflict between friends.', '清晰的沟通是处理朋友间冲突的最好方式。', 'Knowing Me Knowing You', 43, 0, 'senior', 'wordlist', 'required3', 'U1', 'resolve a conflict', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'apologise', 'v.', '/əˈpɒlədʒaɪz/', '道歉,谢罪', 'First, you should apologise to your teammate for your careless words.', '首先,你应为自己不慎的言语向队友道歉。', 'Knowing Me Knowing You', 44, 0, 'senior', 'wordlist', 'required3', 'U1', 'apologise to someone', '美式拼 apologize;美音 /əˈpɑːlədʒaɪz/', 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'honesty', 'n.', '/ˈɒnəsti/', '诚实,正直', 'Honesty is an important value, even when the truth is hard to say.', '诚实是一种重要的品质,即使真相难以启齿。', 'Knowing Me Knowing You', 45, 0, 'senior', 'wordlist', 'required3', 'U1', 'honesty is important', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'communication', 'n.', '/kəˌmjuːnɪˈkeɪʃn/', '沟通,交流', 'Good communication means telling your friend honestly how you feel.', '良好的沟通意味着诚实地告诉朋友你的感受。', 'Knowing Me Knowing You', 46, 0, 'senior', 'wordlist', 'required3', 'U1', 'clear communication', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f3u1.01', '①-ed 分词表原因(主语被…而产生情感)', 'A2', 10, '外研社版必修第三册 U1 — 当状语说明主句动作的原因、且主句主语是该动作的承受者(被动)时,用过去分词 -ed,相当于 Because the subject was done…。如 Disappointed by his behaviour, I told my friend everything.', 1, 'required3', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f3u1.02', '②-ed 分词表时间 / 条件', 'A2', 10, '外研社版必修第三册 U1 — 当状语表示时间(when…)或条件(if…)、且主句主语是该动作的承受者时,用过去分词 -ed。如 Seen from afar, the statue looks alive. / Given more time, we could solve it.', 2, 'required3', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f3u1.03', '③-ed 与 -ing 作状语的区分(看逻辑主语主动还是被动)', 'A2', 10, '外研社版必修第三册 U1 — 状语的逻辑主语=主句主语;主语是动作的承受者(被动)用 -ed,是动作的发出者(主动)用 -ing。本组主语均为承受者,故被动的 -ed 唯一成立,而主动的 -ing 是干扰项。', 3, 'required3', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.01'), '____ by his behaviour, I told my best friend everything.', 'Disappointed', 'Disappointing', 'To disappoint', 'Disappoint', 'A', '主句主语 I 是''被…令失望''的承受者,用过去分词 -ed 表原因(= Because I was disappointed)。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.01'), '____ about her sick friend, Anna could not focus on her homework.', 'Worrying', 'Worried', 'To worry', 'Worry', 'B', 'Anna 是被担忧之事所困的承受者,被动逻辑用 -ed 表原因。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.01'), '____ by the silly mistake, he did not know where to look.', 'Embarrassing', 'To embarrass', 'Embarrassed', 'Embarrass', 'C', 'he 被那个错误弄得难堪,主语是承受者,用 -ed。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.01'), '____ by the loud noise next door, she found it hard to stay calm.', 'Annoying', 'To annoy', 'Annoy', 'Annoyed', 'D', 'she 是被噪音惹恼的一方,被动用 -ed 表原因。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.01'), '____ by the angry shout, the little boy started to cry.', 'Frightened', 'Frightening', 'To frighten', 'Frighten', 'A', 'the little boy 被喊声吓到,主语为承受者,用 -ed。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.01'), '____ by the unkind comment, Mary stayed silent for a while.', 'Shocking', 'Shocked', 'To shock', 'Shock', 'B', 'Mary 被那句刻薄话震到,被动逻辑用 -ed。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.01'), '____ by her warm welcome, the new student felt at home at once.', 'Surprising', 'To surprise', 'Surprised', 'Surprise', 'C', 'the new student 是被热情欢迎打动的承受者,用 -ed。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.01'), '____ with his apology, she decided to forgive him.', 'Pleasing', 'To please', 'Please', 'Pleased', 'D', 'she 被道歉所取悦,主语为承受者,用 -ed 表原因。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.01'), '____ with the result, the coach praised the whole team.', 'Satisfied', 'Satisfying', 'To satisfy', 'Satisfy', 'A', 'the coach 被结果满足,被动逻辑用 -ed。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.01'), '____ by the long argument, both friends just wanted to stop.', 'Tiring', 'Tired', 'To tire', 'Tire', 'B', 'both friends 被争吵弄得疲惫,主语为承受者,用 -ed。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.01'), '____ by the mixed signals, he did not know what she really meant.', 'Confusing', 'To confuse', 'Confused', 'Confuse', 'C', 'he 被含糊的信号弄糊涂,被动用 -ed 表原因。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.01'), '____ by the bad news, he could not sleep that night.', 'Troubling', 'To trouble', 'Trouble', 'Troubled', 'D', 'he 被坏消息所扰,主语为承受者,用 -ed。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.01'), '____ by the sudden change, the children moved closer together.', 'Scared', 'Scaring', 'To scare', 'Scare', 'A', 'the children 被突变吓到,被动逻辑用 -ed 表原因。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.01'), '____ by her kindness, the whole class fell silent.', 'Amazing', 'Amazed', 'To amaze', 'Amaze', 'B', 'the whole class 被她的善意惊到,主语为承受者,用 -ed。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.01'), '____ by the old man''s story, many readers were close to tears.', 'Touching', 'To touch', 'Touched', 'Touch', 'C', 'many readers 被故事打动,被动逻辑用 -ed。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.01'), '____ by his first failure, he almost gave up making friends.', 'Discouraging', 'To discourage', 'Discourage', 'Discouraged', 'D', 'he 被失败挫伤信心,主语为承受者,用 -ed 表原因。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.01'), '____ by his teacher''s words, Tom decided to say sorry first.', 'Inspired', 'Inspiring', 'To inspire', 'Inspire', 'A', 'Tom 被老师的话激励,被动逻辑用 -ed。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.01'), '____ by the endless quarrel, she chose to walk away.', 'Exhausting', 'Exhausted', 'To exhaust', 'Exhaust', 'B', 'she 被无休止的争吵弄得筋疲力尽,主语为承受者,用 -ed。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.01'), '____ by her warm words, the crying child slowly calmed down.', 'Comforting', 'To comfort', 'Comforted', 'Comfort', 'C', 'the crying child 被温暖的话安慰,被动逻辑用 -ed 表原因。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.01'), '____ by the misunderstanding, he wrote a long letter to explain.', 'Frustrating', 'To frustrate', 'Frustrate', 'Frustrated', 'D', 'he 被误会弄得沮丧,主语为承受者,用 -ed。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.02'), '____ this way by a close friend, you are sure to feel hurt.', 'Treated', 'Treating', 'To treat', 'Treat', 'A', '条件状语:主语 you 是''被这样对待''的承受者,用过去分词 -ed(= If you are treated this way)。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.02'), '____ in this way, the problem will soon be solved.', 'Approaching', 'Approached', 'To approach', 'Approach', 'B', '条件状语:the problem 被这样处理,主语为承受者,用 -ed。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.02'), '____ from a distance, the two friends look very much alike.', 'Seeing', 'To see', 'Seen', 'See', 'C', '时间状语:the two friends 是被看的对象,被动逻辑用 -ed(= When they are seen)。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.02'), '____ a second chance, most people will try to do better.', 'Giving', 'To give', 'Give', 'Given', 'D', '条件状语:most people 被给予机会,主语为承受者,用 -ed(= If they are given)。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.02'), '____ about the quarrel, he simply smiled and said nothing.', 'Asked', 'Asking', 'To ask', 'Ask', 'A', '时间状语:he 被问到,被动逻辑用 -ed(= When he was asked)。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.02'), '____ the whole truth, she felt a great sense of relief.', 'Telling', 'Told', 'To tell', 'Tell', 'B', '时间状语:she 被告知真相,主语为承受者,用 -ed。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.02'), '____ alone for too long, anyone may begin to feel lonely.', 'Leaving', 'To leave', 'Left', 'Leave', 'C', '条件状语:anyone 被独自留下,被动逻辑用 -ed(= If one is left)。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.02'), '____ too quickly, a kind person may seem cold and distant.', 'Judging', 'To judge', 'Judge', 'Judged', 'D', '条件状语:a kind person 被仓促评判,主语为承受者,用 -ed。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.02'), '____ with his old friends, his new classmates seem much quieter.', 'Compared', 'Comparing', 'To compare', 'Compare', 'A', '时间/方式状语:his new classmates 是被比较的对象,被动逻辑用 -ed(compared with 固定用法)。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.02'), '____ a sincere apology, she chose to forgive him at once.', 'Offering', 'Offered', 'To offer', 'Offer', 'B', '时间状语:she 被给予一个真诚的道歉,主语为承受者,用 -ed。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.02'), '____ in front of others, even a calm person can feel angry.', 'Criticising', 'To criticise', 'Criticised', 'Criticise', 'C', '条件状语:a calm person 被当众批评,被动逻辑用 -ed(= If criticised)。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.02'), '____ by his friend at last, he felt a heavy weight lift.', 'Forgiving', 'To forgive', 'Forgive', 'Forgiven', 'D', '时间状语:he 被原谅,主语为承受者,用 -ed(= When he was forgiven)。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.02'), '____ by her parents, the shy girl slowly opened up to others.', 'Encouraged', 'Encouraging', 'To encourage', 'Encourage', 'A', '时间状语:the shy girl 被父母鼓励,被动逻辑用 -ed。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.02'), '____ in time, we could have avoided the silly argument.', 'Warning', 'Warned', 'To warn', 'Warn', 'B', '条件状语:we 被及时提醒,主语为承受者,用 -ed(= If we had been warned)。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.02'), '____ by those around him, a person feels safe to be honest.', 'Respecting', 'To respect', 'Respected', 'Respect', 'C', '条件状语:a person 被周围的人尊重,被动逻辑用 -ed。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.02'), '____ by his teammates again, he promised never to gossip.', 'Trusting', 'To trust', 'Trust', 'Trusted', 'D', '时间状语:he 被队友重新信任,主语为承受者,用 -ed。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.02'), '____ for something he did not do, he stayed surprisingly calm.', 'Blamed', 'Blaming', 'To blame', 'Blame', 'A', '时间状语:he 被指责,被动逻辑用 -ed(= When he was blamed)。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.02'), '____ to the party by a kind classmate, the new boy felt welcome.', 'Inviting', 'Invited', 'To invite', 'Invite', 'B', '时间状语:the new boy 被邀请,主语为承受者,用 -ed。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.02'), '____ by good friends, we can get through almost any trouble.', 'Supporting', 'To support', 'Supported', 'Support', 'C', '条件状语:we 被好友支持,被动逻辑用 -ed(= If we are supported)。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.02'), '____ by the people closest to us, we feel much less alone.', 'Understanding', 'To understand', 'Understand', 'Understood', 'D', '时间状语:we 被最亲近的人理解,主语为承受者,用 -ed。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.03'), '____ by her own words, Lily wished she could disappear.', 'Embarrassed', 'Embarrassing', 'To embarrass', 'Embarrass', 'A', '逻辑主语 Lily 是被难堪的一方(被动),用 -ed;主动的 -ing 表''令人难堪'',与此处主语不符。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.03'), '____ about the school trip, the children could hardly sit still.', 'Exciting', 'Excited', 'To excite', 'Excite', 'B', 'the children 是被激动的一方(被动)用 -ed;-ing 表''令人兴奋''指事物,不指人。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.03'), '____ in psychology, she read every book on emotions she could find.', 'Interesting', 'To interest', 'Interested', 'Interest', 'C', 'she 对…感兴趣(被动感受)用 -ed;-ing 表''有趣的''指事物。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.03'), '____ of the endless gossip, he decided to change the subject.', 'Tiring', 'To tire', 'Tire', 'Tired', 'D', 'be tired of 厌倦,he 是承受者,用 -ed;-ing 表''令人疲惫的''指事物。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.03'), '____ to her friends, she always keeps their secrets safe.', 'Devoted', 'Devoting', 'To devote', 'Devote', 'A', 'be devoted to 忠诚于,she 处于被动状态用 -ed;主动 -ing 在此不成立。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.03'), '____ about being late, Tom ran all the way to meet his friend.', 'Worrying', 'Worried', 'To worry', 'Worry', 'B', 'Tom 是被担心情绪占据的一方(被动)用 -ed;-ing 表''令人担忧的''指事物。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.03'), '____ with the kind reply, she smiled and said thank you.', 'Pleasing', 'To please', 'Pleased', 'Please', 'C', 'she 被取悦(被动)用 -ed;主动的 -ing 表''讨人喜欢的'',与主语不符。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.03'), '____ at the rude message, Ben read it again to be sure.', 'Shocking', 'To shock', 'Shock', 'Shocked', 'D', 'Ben 是被震惊的一方(被动)用 -ed;-ing 表''令人震惊的''指事物。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.03'), '____ of saying the wrong thing, the new student stayed quiet.', 'Frightened', 'Frightening', 'To frighten', 'Frighten', 'A', 'be frightened of 害怕,the new student 是承受者用 -ed;主动 -ing 不成立。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.03'), '____ by the long speech, several students began to look away.', 'Boring', 'Bored', 'To bore', 'Bore', 'B', 'several students 是被弄得无聊的一方(被动)用 -ed;-ing 表''无聊的''指事物。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.03'), '____ by the constant complaints, she finally spoke up.', 'Annoying', 'To annoy', 'Annoyed', 'Annoy', 'C', 'she 是被惹恼的一方(被动)用 -ed;主动的 -ing 表''烦人的''指事物。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.03'), '____ at how kind strangers can be, he wrote about it in his diary.', 'Amazing', 'To amaze', 'Amaze', 'Amazed', 'D', 'he 是被惊叹打动的一方(被动)用 -ed;-ing 表''令人惊叹的''指事物。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.03'), '____ by his mixed signals, Mary asked him to explain clearly.', 'Confused', 'Confusing', 'To confuse', 'Confuse', 'A', 'Mary 是被弄糊涂的一方(被动)用 -ed;-ing 表''令人困惑的''指事物。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.03'), '____ with his honest answer, the teacher nodded and smiled.', 'Satisfying', 'Satisfied', 'To satisfy', 'Satisfy', 'B', 'the teacher 被满足(被动)用 -ed;主动的 -ing 表''令人满意的''指事物。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.03'), '____ in himself, he promised to think before speaking next time.', 'Disappointing', 'To disappoint', 'Disappointed', 'Disappoint', 'C', 'he 对自己失望(被动感受)用 -ed;-ing 表''令人失望的''指事物。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.03'), '____ by the angry voices, the small dog hid under the table.', 'Scaring', 'To scare', 'Scare', 'Scared', 'D', 'the small dog 是被吓到的一方(被动)用 -ed;-ing 表''吓人的''指事物。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.03'), '____ by the sudden apology, she did not know what to say.', 'Surprised', 'Surprising', 'To surprise', 'Surprise', 'A', 'she 是被惊到的一方(被动)用 -ed;主动的 -ing 表''令人惊讶的''指事物。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.03'), '____ by her friend''s support, she felt warm inside.', 'Touching', 'Touched', 'To touch', 'Touch', 'B', 'she 被打动(被动)用 -ed;-ing 表''动人的''指事物。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.03'), '____ after the long argument, both of them wanted some quiet.', 'Exhausting', 'To exhaust', 'Exhausted', 'Exhaust', 'C', 'both of them 是被累垮的一方(被动)用 -ed;-ing 表''令人疲惫的''指事物。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U1' AND code='f3u1.03'), '____ by the old fable, the class talked about keeping a good distance.', 'Inspiring', 'To inspire', 'Inspire', 'Inspired', 'D', 'the class 被寓言启发(被动)用 -ed;主动的 -ing 表''鼓舞人心的''指事物。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Loose Lips Sink Ships', 'Ben, aged seventeen, was a key member of his school basketball team. After his team lost an important match, he felt sure that one player, the point guard, had let everyone down. Still angry, Ben told his best friend exactly what he thought of his teammate. He was only letting off steam, but his friend later repeated every word to the rest of the team. Now Ben feels embarrassed and ashamed, and he cannot concentrate on anything. So he wrote to an agony aunt for advice. She reminded him of an old saying: speaking too freely can cause all kinds of trouble. The real problem, she explained, was not only his friend''s loose lips but also Ben''s own habit of talking without thinking. Her advice was simple. First, he should apologise to his teammate. Then he should tell his friend honestly that he felt hurt, but that he wanted to move on. Most importantly, he should learn to take a breath and calm down before he speaks.', '记叙·知心姐姐为本解忧', 167, '[{"q":"What is the main idea of the passage?","answer":"A","options":["Ben spoke carelessly when he was angry and is advised how to put things right.","Ben''s team won the match because of his point guard.","Ben decided to leave the basketball team for good.","Ben''s friend asked the agony aunt for help with sport."],"explanation":"全文围绕本气头上说错话、知心姐姐教他如何弥补,这是对主旨的概括。"},{"q":"Why does Ben feel embarrassed and ashamed now?","answer":"B","options":["He missed the most important shot of the game.","His private complaint was passed on to the whole team.","He forgot the name of his own teammate.","He refused to join the team practice."],"explanation":"因为他私下的抱怨被朋友转告给全队,这是对原文情节的转述。"},{"q":"What does the agony aunt suggest Ben do first?","answer":"A","options":["Say sorry to the teammate he had talked about.","Stop speaking to his friend forever.","Blame the point guard in front of the coach.","Quit the team and find a new hobby."],"explanation":"知心姐姐建议他先向那位队友道歉,是对''First, apologise''一句的转述。"}]'::jsonb, '[{"word":"agony aunt","cn":"知心姐姐"},{"word":"let off steam","cn":"发泄情绪"},{"word":"loose lips","cn":"口无遮拦"}]'::jsonb, 2, 'required3', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Little White Lies', 'Most of us say that honesty matters and that lying is wrong, yet who can claim they have never told a lie? Often we comfort ourselves by calling them white lies, the little untruths we tell to protect others. Imagine a friend cooks a meal you secretly dislike. Many people will smile and say it is delicious. If a classmate asks about a new haircut, we may say it looks great even when we think the opposite. But are these kind words really meant to help the other person? Sometimes we lie to protect ourselves from another person''s disappointment or anger. We may also lie to give encouragement, telling a friend that his singing is wonderful, when honest comments would help him improve far more. Even small lies can have results we cannot predict. The meal you praised may be served again and again. If your friend later learns the truth, will he still trust your opinion? Honesty, in the end, may be the kinder choice.', '说明·善意谎言到底好不好', 166, '[{"q":"What does the writer say a white lie is?","answer":"B","options":["A serious crime against the law.","A small untruth told to protect other people.","A way of making money from friends.","A kind of joke that everyone enjoys."],"explanation":"原文把 white lie 解释为''为保护他人而说的小谎'',这是对定义的转述。"},{"q":"According to the writer, why do we sometimes tell white lies?","answer":"C","options":["To win prizes at school.","To learn a foreign language faster.","To avoid facing another person''s anger or disappointment.","To remember more new words."],"explanation":"原文指出我们有时撒谎是为避免对方的失望或愤怒,这是对该原因的转述。"},{"q":"What does the writer suggest about white lies in the end?","answer":"D","options":["They always make friendships much stronger.","They should be told as often as possible.","They never cause any kind of problem.","They can lead to results we cannot foresee, so honesty may be kinder."],"explanation":"结尾指出小谎可能带来无法预料的后果,诚实或许更善良,这是对结论的概括。"}]'::jsonb, '[{"word":"deceive","cn":"欺骗"},{"word":"frank","cn":"坦率的"},{"word":"honesty","cn":"诚实"}]'::jsonb, 2, 'required3', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'The Porcupine Dilemma', 'One cold winter night, a group of porcupines gathered together to keep warm. As soon as they moved closer, the sharp spines on their bodies hurt one another, so they had to move apart. After a short while, they began to feel cold again, and once more they pushed together for warmth. But again the pain of the spines forced them away. They repeated this process several times. At last, they found the ideal distance, one that was close enough to share warmth yet far enough to avoid hurting each other. This old story tells us something true about human relationships. Like the porcupines, people need each other for comfort and support, but they also need a little space. When friends stand too close, small differences may begin to hurt. When they stay too far apart, they feel cold and lonely. The wisest friendships, the fable suggests, are those that find a comfortable distance, where two people can be warm together without causing each other pain.', '寓言·人际关系中的界限', 166, '[{"q":"Why did the porcupines keep moving closer and then apart?","answer":"A","options":["They wanted warmth but their spines hurt one another.","They were looking for food in the snow.","They were playing a winter game together.","They were trying to find their way home."],"explanation":"豪猪靠近是为取暖,但刺会扎到彼此,所以又分开,这是对情节的转述。"},{"q":"What did the porcupines finally discover?","answer":"B","options":["That they should never stay together.","A distance that was both warm and safe.","That winter was not really cold at all.","A warmer cave far from the others."],"explanation":"它们最终找到了既温暖又不伤人的理想距离,这是对结局的转述。"},{"q":"What lesson does the fable teach about friendship?","answer":"C","options":["Friends should share everything they own.","People are happier living completely alone.","Good relationships need a comfortable distance.","Differences between friends never matter."],"explanation":"寓言告诉我们好的关系需要舒适的距离,这是对寓意的概括。"}]'::jsonb, '[{"word":"apart","cn":"分开"},{"word":"independent","cn":"独立的"},{"word":"fence","cn":"界限;篱笆"}]'::jsonb, 2, 'required3', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Saying No Politely', 'Emotional quotient, often shortened to EQ, is a measure of how well we recognise our own feelings and those of other people. Many experts believe that EQ can matter even more than IQ in everyday life, especially when we deal with friends and classmates. One important skill of emotional intelligence is being able to say no in a kind way. Refusing a request is never easy, because we do not want to upset the person who is asking. Yet always saying yes can leave us tired and unhappy. The secret is in how we refuse. A polite no usually begins with a few words of regret, such as I am sorry or I would really like to. Next, we give a simple reason, perhaps that we are busy at that time. If we can, we offer another choice, like meeting next week instead. Refusing this way shows respect for the other person''s feelings while still being honest about our own. With a little practice, saying no can become far less frightening.', '说明·情商与礼貌拒绝', 171, '[{"q":"What does EQ measure, according to the passage?","answer":"D","options":["How fast a person can run.","How many words a person can spell.","How much money a person can earn.","How well we understand feelings, our own and others''."],"explanation":"EQ 衡量我们对自己和他人情绪的理解程度,这是对定义的转述。"},{"q":"Why does the writer say always saying yes can be a problem?","answer":"A","options":["It can leave us feeling worn out and low.","It makes other people angry at once.","It is against the school rules.","It costs a lot of money."],"explanation":"原文指出总是答应会让我们疲惫又不快乐,这是对该观点的转述。"},{"q":"What is the writer''s advice for a polite refusal?","answer":"B","options":["Say nothing and walk away quickly.","Start with regret, give a reason, and offer another choice.","Always agree and then change your mind later.","Ask someone else to refuse for you."],"explanation":"建议先表达歉意、给出理由、再提供其他选择,这是对礼貌拒绝步骤的概括。"}]'::jsonb, '[{"word":"concern","cn":"关心;担忧"},{"word":"strategy","cn":"策略"},{"word":"complexity","cn":"复杂性"}]'::jsonb, 2, 'required3', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Tips for Healthy Relationships', 'Strong and happy relationships do not just happen by accident; they are built day by day through small, kind actions. Here are a few simple tips. First, try to forgive others when they apologise, because saying sorry is hard for anyone, and a little understanding goes a long way. Second, always tell the truth, even when honesty is difficult, since trust is the core of every friendship. Third, do not judge people too quickly; it takes time to know what someone is really like. Fourth, try not to complain about others all the time, and instead look on the bright side of things. Finally, never criticise a friend in front of other people, as this can cause real embarrassment and hurt. None of these tips is hard to understand, yet they are easy to forget when we feel annoyed or tired. The good news is that the more we practise them, the more natural they become. In time, kindness turns into a habit, and our friendships grow deeper and stronger.', '建议·维持友好关系的小贴士', 170, '[{"q":"How are strong relationships built, according to the passage?","answer":"C","options":["By spending a lot of money on gifts.","By chance, without any effort.","Through small kind actions, day after day.","Only by living in the same house."],"explanation":"原文说牢固的关系靠日复一日的小善举建立,这是对首句的转述。"},{"q":"Why does the writer say we should tell the truth?","answer":"D","options":["Because lying is against the law.","Because the truth is always easy to say.","Because friends enjoy hearing bad news.","Because trust is at the heart of every friendship."],"explanation":"原文指出信任是友谊的核心,所以要说真话,这是对该理由的转述。"},{"q":"What does the writer say about criticising a friend?","answer":"A","options":["Doing it in front of others can cause real hurt.","It should be done as loudly as possible.","It is the best way to make friends.","It never affects a friendship at all."],"explanation":"原文提醒不要当众批评朋友,否则会造成真正的尴尬与伤害,这是对该建议的转述。"}]'::jsonb, '[{"word":"forgive","cn":"原谅"},{"word":"criticise","cn":"批评"},{"word":"core","cn":"核心的"}]'::jsonb, 2, 'required3', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'A Lesson in Trust', 'When Lin first joined her new class, she found it hard to fit in. One girl, Mei, was especially friendly, and soon the two shared everything. One afternoon, feeling annoyed, Lin told Mei a small secret about another classmate. She was only letting off steam and did not really mean it. To her shock, the story spread around the class by the next morning. Lin felt both embarrassed and angry. At first she wanted to blame Mei for her loose lips, but then she remembered that she herself had started the gossip. Taking a deep breath, she decided to face the problem honestly. She apologised to the classmate she had talked about, and she told Mei calmly that she felt let down. Mei was surprised by Lin''s honesty, and she said sorry too. From that day on, both girls learned to think before they spoke. Their friendship did not break; instead, it grew stronger, built on a new and deeper kind of trust.', '记叙·一次关于信任的经历', 163, '[{"q":"What did Lin do when she felt annoyed one afternoon?","answer":"B","options":["She left the class and went home.","She shared a secret about another classmate with Mei.","She wrote a letter to her teacher.","She refused to speak to anyone for a week."],"explanation":"林恼火时把另一位同学的秘密告诉了梅,这是对情节的转述。"},{"q":"How did Lin deal with the problem in the end?","answer":"C","options":["She blamed Mei and ended the friendship.","She pretended that nothing had happened.","She faced it honestly and apologised.","She told even more secrets to everyone."],"explanation":"林最终诚实面对、主动道歉,这是对结局的转述。"},{"q":"What happened to the friendship between Lin and Mei?","answer":"D","options":["It ended completely after the quarrel.","It stayed exactly the same as before.","It turned into a serious fight.","It grew stronger and more trusting."],"explanation":"她们的友谊没有破裂,反而建立在更深的信任上变得更牢固,这是对结尾的转述。"}]'::jsonb, '[{"word":"annoyed","cn":"恼怒的"},{"word":"let down","cn":"辜负;使失望"},{"word":"moreover","cn":"此外"}]'::jsonb, 2, 'required3', 'U1', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U1', 'Learning to Say Sorry', 'Saying sorry is never (1)____, but it is one of the most important skills in any friendship. When we make a (2)____, our first feeling is often to defend ourselves. However, a sincere apology can (3)____ a damaged relationship more quickly than we expect. The key is to speak (4)____ and to take full responsibility, instead of blaming others. We should also (5)____ carefully to how the other person feels. Sometimes a few honest words are (6)____ to repair the trust between two friends. If we keep silent, a small problem may slowly (7)____ into a much bigger one. So next time you cause (8)____, take a deep breath, calm (9)____, and say the simple words, ''I am sorry.'' You may be (10)____ at how much better both of you feel afterwards.', 132, 2, '[{"q":"1","answer":"A","options":["easy","rich","tall","late"],"explanation":"never easy 从来不容易;其余形容词与语境不符。"},{"q":"2","answer":"B","options":["song","mistake","price","garden"],"explanation":"make a mistake 犯错。"},{"q":"3","answer":"C","options":["sell","throw","repair","lose"],"explanation":"repair a relationship 修复关系。"},{"q":"4","answer":"D","options":["secretly","angrily","carelessly","honestly"],"explanation":"speak honestly 坦诚地说;其余与''承担责任''矛盾。"},{"q":"5","answer":"A","options":["listen","shout","run","eat"],"explanation":"listen to how someone feels 倾听感受。"},{"q":"6","answer":"B","options":["empty","enough","wrong","late"],"explanation":"be enough to 足以。"},{"q":"7","answer":"C","options":["fall","sell","grow","sleep"],"explanation":"grow into 发展成。"},{"q":"8","answer":"D","options":["music","weather","paint","trouble"],"explanation":"cause trouble 惹麻烦。"},{"q":"9","answer":"A","options":["down","up","off","in"],"explanation":"calm down 冷静下来。"},{"q":"10","answer":"B","options":["bored","surprised","angry","asleep"],"explanation":"be surprised at 对…感到惊讶。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U1', 'The Power of Honest Words', 'My friend Tom once asked me what I thought of his singing. To be (1)____, I did not think it was very good, but I almost said it was wonderful. That would have been a white (2)____. In the end, I decided to tell the (3)____ in a kind way. I said that his voice was pleasant, but that he could (4)____ his timing with a little practice. At first he looked a bit (5)____, and I was afraid I had hurt him. However, a week later he (6)____ me to say thank you. My honest words had helped him (7)____ his singing, while empty praise would have taught him (8)____. From that day, I understood that real friends are not afraid to give (9)____ comments. Honesty, when it comes with kindness, is a true (10)____ of friendship.', 138, 2, '[{"q":"1","answer":"C","options":["hungry","famous","honest","sleepy"],"explanation":"to be honest 老实说。"},{"q":"2","answer":"D","options":["song","price","road","lie"],"explanation":"a white lie 善意的谎言。"},{"q":"3","answer":"A","options":["truth","weather","money","noise"],"explanation":"tell the truth 说真话。"},{"q":"4","answer":"B","options":["break","improve","forget","lose"],"explanation":"improve his timing 改进节奏。"},{"q":"5","answer":"C","options":["proud","rich","hurt","tall"],"explanation":"look hurt 显得受伤;其余与''怕伤到他''不符。"},{"q":"6","answer":"D","options":["sold","left","lost","called"],"explanation":"called me to say thank you 打电话道谢。"},{"q":"7","answer":"A","options":["improve","drop","hide","waste"],"explanation":"help him improve 帮他进步。"},{"q":"8","answer":"B","options":["everything","nothing","something","anywhere"],"explanation":"would have taught him nothing 什么也教不会。"},{"q":"9","answer":"C","options":["silly","false","frank","lazy"],"explanation":"frank comments 坦率的评价。"},{"q":"10","answer":"D","options":["price","machine","garden","sign"],"explanation":"a sign of friendship 友谊的标志。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U1', 'Giving Friendship Some Space', 'When Anna and I became best friends, we did almost everything (1)____. We sat together, walked home together, and shared every (2)____. At first it felt wonderful, but slowly we began to (3)____ over small things. I felt she was always (4)____ my time, and she felt I was too far (5)____. One day our teacher told us an old story about two animals that needed each other for (6)____ but also got hurt when they stood too close. The story made us (7)____ that even close friends need a little space. After that, we gave each other room to be (8)____. I joined the art club, and she joined the choir. To our (9)____, our friendship did not grow weaker; it actually grew (10)____. A good distance, we learned, can keep a friendship healthy.', 135, 2, '[{"q":"1","answer":"A","options":["together","alone","again","early"],"explanation":"do everything together 一起做每件事。"},{"q":"2","answer":"B","options":["price","secret","garden","machine"],"explanation":"share every secret 分享每个秘密。"},{"q":"3","answer":"C","options":["agree","sleep","argue","travel"],"explanation":"argue over small things 因小事争吵。"},{"q":"4","answer":"D","options":["selling","washing","drawing","taking"],"explanation":"taking my time 占用我的时间。"},{"q":"5","answer":"A","options":["away","near","above","inside"],"explanation":"too far away 太疏远。"},{"q":"6","answer":"B","options":["money","warmth","noise","weather"],"explanation":"need each other for warmth 互相取暖。"},{"q":"7","answer":"C","options":["forget","doubt","realise","refuse"],"explanation":"made us realise 让我们意识到。"},{"q":"8","answer":"D","options":["asleep","absent","afraid","independent"],"explanation":"room to be independent 各自独立的空间。"},{"q":"9","answer":"A","options":["surprise","sorrow","anger","fear"],"explanation":"to our surprise 令我们惊讶的是。"},{"q":"10","answer":"B","options":["smaller","stronger","shorter","colder"],"explanation":"grew stronger 变得更牢固。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U1', 'How to Refuse Politely', 'Learning to say no is an important (1)____ in life. When a classmate asked me to watch a boxing match, I did not really want to go, but I was (2)____ to hurt his feelings. For a moment I almost said yes against my (3)____ wish. Then I remembered a useful tip about (4)____ refusals. First, I should begin with a few words of (5)____, such as ''I am really sorry.'' Next, I should give a simple (6)____, like being busy that evening. Finally, if possible, I should (7)____ another choice. So I told him kindly that I could not come, but that we could meet for lunch (8)____. To my relief, he smiled and said it was no (9)____ at all. Saying no had felt frightening, yet doing it politely turned out to be quite (10)____. Now I no longer always say yes just to please others.', 148, 2, '[{"q":"1","answer":"C","options":["price","garden","skill","noise"],"explanation":"an important skill 重要技能。"},{"q":"2","answer":"D","options":["happy","ready","free","afraid"],"explanation":"afraid to hurt his feelings 怕伤到他。"},{"q":"3","answer":"A","options":["real","rich","loud","late"],"explanation":"against my real wish 违背真实意愿。"},{"q":"4","answer":"B","options":["angry","polite","lazy","silly"],"explanation":"polite refusals 礼貌拒绝。"},{"q":"5","answer":"C","options":["music","weather","regret","price"],"explanation":"words of regret 表示歉意的话。"},{"q":"6","answer":"D","options":["song","machine","ticket","reason"],"explanation":"give a reason 给个理由。"},{"q":"7","answer":"A","options":["offer","break","lose","throw"],"explanation":"offer another choice 提供别的选择。"},{"q":"8","answer":"B","options":["already","instead","hardly","nowhere"],"explanation":"meet for lunch instead 改为一起吃午饭。"},{"q":"9","answer":"C","options":["garden","machine","trouble","ticket"],"explanation":"no trouble at all 一点也不麻烦。"},{"q":"10","answer":"D","options":["wrong","empty","late","easy"],"explanation":"quite easy 相当容易。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U1', 'Forgiving a Friend', 'Last term, my best friend forgot my birthday, and I felt deeply (1)____. For days I would not speak to her, and our friendship seemed to grow (2)____. Then one evening she came to me with (3)____ in her eyes and said she was truly sorry. She explained that her grandmother had been ill, and she had simply (4)____ the date by accident. Hearing this, I felt my anger slowly (5)____ away. I realised that holding on to it was only hurting (6)____ of us. Saying sorry had not been easy for her, and (7)____ her was not easy for me. But I knew that forgiveness was the (8)____ choice. So I gave her a hug and told her it was all (9)____. From that day, our friendship felt warmer than before, because we both learned that nobody is (10)____, and real friends give each other a second chance.', 149, 2, '[{"q":"1","answer":"A","options":["hurt","rich","tall","proud"],"explanation":"feel deeply hurt 深感受伤。"},{"q":"2","answer":"B","options":["warmer","colder","louder","richer"],"explanation":"grow colder 变得冷淡。"},{"q":"3","answer":"C","options":["prices","songs","tears","tickets"],"explanation":"with tears in her eyes 眼含泪水。"},{"q":"4","answer":"D","options":["sold","broken","washed","forgotten"],"explanation":"forgotten the date 忘了日期。"},{"q":"5","answer":"A","options":["melt","fall","jump","climb"],"explanation":"anger melt away 怒气消散。"},{"q":"6","answer":"B","options":["none","both","neither","either"],"explanation":"hurting both of us 伤害我们俩。"},{"q":"7","answer":"C","options":["selling","leaving","forgiving","losing"],"explanation":"forgiving her 原谅她。"},{"q":"8","answer":"D","options":["wrong","empty","late","right"],"explanation":"the right choice 正确的选择。"},{"q":"9","answer":"A","options":["fine","wrong","gone","lost"],"explanation":"it was all fine 一切都好了。"},{"q":"10","answer":"B","options":["tall","perfect","rich","famous"],"explanation":"nobody is perfect 人无完人。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U1', 'Reading People''s Feelings', 'Some people seem to know exactly how others (1)____. They notice when a friend is sad, even if that friend (2)____ nothing. This ability to read feelings is part of what we call emotional (3)____. People with this skill are good at building (4)____ relationships, because they think about others as well as (5)____. When a classmate looks worried, they offer a kind (6)____ instead of ignoring the problem. When someone is angry, they stay calm and try to (7)____ the conflict gently. They also understand their own emotions, so they take a deep (8)____ before they speak in anger. Such skills are not something we are (9)____ with; they can be learned step by step. By watching, listening and caring, anyone can slowly (10)____ how to understand the people around them.', 132, 2, '[{"q":"1","answer":"C","options":["sell","drive","feel","cook"],"explanation":"how others feel 别人的感受。"},{"q":"2","answer":"D","options":["sells","buys","drops","says"],"explanation":"says nothing 什么也不说。"},{"q":"3","answer":"A","options":["intelligence","machine","garden","price"],"explanation":"emotional intelligence 情商。"},{"q":"4","answer":"B","options":["empty","healthy","broken","silent"],"explanation":"healthy relationships 健康的关系。"},{"q":"5","answer":"C","options":["nobody","nothing","themselves","nowhere"],"explanation":"as well as themselves 也想到自己。"},{"q":"6","answer":"D","options":["price","ticket","stone","word"],"explanation":"a kind word 一句体贴的话。"},{"q":"7","answer":"A","options":["resolve","start","break","lose"],"explanation":"resolve the conflict 化解冲突。"},{"q":"8","answer":"B","options":["price","breath","garden","machine"],"explanation":"take a deep breath 深吸一口气。"},{"q":"9","answer":"C","options":["sold","left","born","lost"],"explanation":"born with 与生俱来。"},{"q":"10","answer":"D","options":["forget","lose","waste","learn"],"explanation":"learn how to understand 学会理解。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U1 听力·对话 Can I Stay at Your Place?', '外研社版必修第三册 U1 · dialogue', 3, 'Tina: Hi Kerry, have you got a minute? I need a favour.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U1 听力·短文 Saying No Politely', '外研社版必修第三册 U1 · passage', 2, 'Being able to say no politely is an important part of emotional intelligence.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U1 听力·对话 I Heard What You Said', '外研社版必修第三册 U1 · dialogue', 3, 'Sam: Leo, I need to talk to you. I''m a bit upset.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U1 听力·短文 The Truth About White Lies', '外研社版必修第三册 U1 · passage', 2, 'Many people tell small white lies to protect the feelings of others.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U1 听力·对话 Thanks, but No Thanks', '外研社版必修第三册 U1 · dialogue', 3, 'Mike: Hi Ryan, would you like to come to a boxing match on Saturday?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U1 听力·短文 The Porcupines'' Distance', '外研社版必修第三册 U1 · passage', 2, 'On a cold night, a group of porcupines moved together to keep warm.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (10, 'Write an Essay on the Importance of Honesty(写一篇关于诚实重要性的议论文)', 'Why Honesty Matters in Friendship', '假设你叫李华,班级正在举办以''诚实''为主题的英语演讲。请用英语写一篇约100词的短文,内容包括:① 用一句话说明你的观点——在友谊中诚实为什么重要;② 给出一两条理由,并用一个生活中的例子加以支持;③ 用一句结论收尾,呼应标题。注意:按引言—正文—结论组织,结论中不引入新内容;尽量用本单元 -ed 分词作状语的句子(如 Disappointed by a lie, …)。', 'Suppose you are Li Hua. Your class is holding an English talk on the theme of honesty. Write an essay (about 100 words) including: 1) one sentence stating your opinion — why honesty matters in friendship; 2) one or two reasons supported by a real-life example; 3) a conclusion that links back to the title. Organise it as introduction, main body and conclusion, and do not add new ideas in the conclusion. Try to use an -ed participle as an adverbial (e.g. Disappointed by a lie, …).', '["引言:点明观点(I believe that honesty is the core of every true friendship.)","正文理由+例子(One reason is that … . For example, …)","用 -ed 分词作状语支持论证(Hurt by a small lie, … / Trusted by others, …)","结论呼应标题、不引入新内容(In conclusion, …)"]'::jsonb, 70, 100, 'I firmly believe that honesty is the core of every true friendship. Without it, trust cannot grow, and even the closest friends may slowly drift apart.
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (10, 'required3', 'U1', '{"title":"-ed 分词作状语速查","intro":"过去分词(-ed)作状语,逻辑主语就是主句主语;当主语是动作的承受者(被动)时用 -ed,可表原因、时间或条件。判断口诀:主语''被怎么样''→ 用 -ed;主语''主动做''→ 用 -ing。","table":{"headers":["用法","例句 / 等价从句"],"rows":[["原因","Disappointed by his behaviour, I told my friend. = Because I was disappointed …"],["时间","Seen from afar, the statue looks alive. = When it is seen from afar …"],["条件","Given more time, we could solve it. = If we were given more time …"],["-ed vs -ing","Worried about her, Joy helped.(被动→-ed) / Believing she is right, Joy leads.(主动→-ing)"]]},"specialRules":[{"rule":"逻辑主语=主句主语,且主语是动作承受者(被动)→ 用过去分词 -ed","mark":"Treated this way, you feel hurt(you 被这样对待)"},{"rule":"主语是动作发出者(主动)→ 用现在分词 -ing","mark":"Filled with anger, he spoke without thinking 对比 Smiling kindly, she helped me"},{"rule":"情感类动词:人''被…''的感受用 -ed(interested/worried),''令人…''的性质用 -ing(interesting/worrying)","mark":"I was interested. / The book is interesting."},{"rule":"-ed 分词状语常可还原为 because / when / if 引导的状语从句","mark":"Approached in this way = If it is approached in this way"}],"why":["过去分词本身含被动、完成意味;作状语时它紧扣主句主语,只要主语是这个动作的''承受方'',就用 -ed,而无需写出完整的被动从句,句子更简洁地道。"],"gaokaoPoints":["语法填空/短文改错高频:给动词,据逻辑主语判断填 -ed(被动)还是 -ing(主动)。","句首独立的 -ed/-ing 状语,务必核对它的逻辑主语与主句主语一致(避免''垂悬分词'')。"],"examVsReal":[{"exam":"Disappointed by his behaviour, I told my friend everything.(考试/书面)","real":"I was so disappointed by what he did that I told my friend everything.","note":"考试爱考分词状语的简洁形式;日常口语常直接用从句或并列句,更自然。"},{"exam":"Given more time, we could finish it.(考试)","real":"If we had more time, we could finish it.","note":"考试用 -ed 分词表条件;口语里直接说 if 从句更常见。"}]}'::jsonb, 'fltrp');
